script:
async () => {
  // Mac M2 session, M12 fix round, measurement B: the GPU profiler in Safari 27.0.1 on a
  // scene with transparents, so that the transparent sort runs live. M12 measured the
  // Lighting tab and a one-quad opaque scene: no transparent-sort/* entry.
  // Scene: the M8 bench scene. The code from `WIDTH` to the spawn loop is copied from
  // docs/plans/assets/2026-09-27-transparent-sort-bench.js at HEAD (constants, helpers,
  // mulberry32 seeded n * 2 for 'same', positions, 16x16 px quads, .transparent()), with
  // N = 10 000 and depth 'same', target 1920x1080, lighting off, on ?mode=B&bench. The
  // bench measures one 120-frame window and destroys its quads; here they stay while three
  // windows are measured:
  //   first:  the first 120 valid frames after the page's FIRST enableGpuProfiling(), which
  //           builds the GpuProfiler, and with it a fresh query set;
  //   steady: then, with no reset, at least STEADY_FRAMES rAF frames;
  //   reset:  disableGpuProfiling(); enableGpuProfiling() in one turn (a reset: the same query
  //           set, the stamp history forgotten), then the first 120 valid frames after it.
  // A temporary wrapper on the live profiler instance (own properties on `consume` and on
  // `history.record`, calling the originals; deleted at the end and checked) records every
  // consumed frame of `first` and `reset`: its pairs, its stamps, kept or discarded. The code
  // does not change. A pair raced by the resolve (M12, anomaly 2) holds the stamps written at
  // its index by an earlier frame: on the first frame after an enable or a reset the history
  // does not know them, so the profiler cannot call the frame `stale` (timestamp-frames.ts,
  // StampHistory). The record checks it directly: `repeatsPrevious` (a worked pair equal, at its
  // index, to the previous consumed frame) and the offsets of every worked pair from the
  // frame's median beginning and end (a pair from an earlier frame lies a frame period away).
  const WIDTH = 1920;
  const HEIGHT = 1080;
  const QUAD_PX = 16;
  const WINDOW = 120;
  const TIMEOUT_MS = 180000;
  const N = 10000;
  const zMode = 'same';
  const STEADY_FRAMES = window.__sortSteadyFrames ?? 1200;
  const LOG_MAX = 130;

  const engine = window.__hyperion;
  if (!engine) throw new Error('window.__hyperion is missing: open the dev harness');
  if (!new URLSearchParams(location.search).has('bench')) throw new Error('run on a ?bench page');
  if (!engine.gpuProfilingSupported) throw new Error('no timestamp-query on this device');

  const frames = (n) => new Promise((resolve) => {
    const step = (left) => (left <= 0 ? resolve() : requestAnimationFrame(() => step(left - 1)));
    step(n);
  });
  const gpuCount = () => new Promise((resolve) => {
    const hook = (_dt, views) => {
      engine.removeHook('frameEnd', hook);
      resolve(views ? views.entityCount : 0);
    };
    engine.addHook('frameEnd', hook);
  });
  const until = async (what, predicate) => {
    const start = performance.now();
    while (!(await predicate())) {
      if (performance.now() - start > TIMEOUT_MS) throw new Error(`timed out after ${TIMEOUT_MS} ms waiting for ${what}`);
      await frames(1);
    }
  };
  const settledAt = (n) => until(`${n} entities on the GPU`, async () => engine.stats.overflowCount === 0 && (await gpuCount()) === n);
  const prng = (seed) => () => {
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };

  const out = { startedAt: new Date().toISOString(), timeOrigin: performance.timeOrigin, visibilityAtStart: document.visibilityState };
  engine.lighting.setBackend('off');
  engine.resize(WIDTH, HEIGHT);
  engine.cam.position(0, 0, 0);
  engine.cam.zoom(1);
  await settledAt(0);
  await frames(4);
  const vp = engine.cam.viewProjection;
  const halfW = 1 / vp[0];
  const halfH = 1 / vp[5];
  const size = (QUAD_PX * 2 * halfW) / WIDTH;
  const spanX = halfW - size / 2;
  const spanY = halfH - size / 2;
  const n = N;
  const rand = prng(n * 2 + (zMode === 'distinct' ? 1 : 0));
  const handles = [];
  engine.batch(() => {
    for (let i = 0; i < n; i++) {
      const h = engine.spawn({ mode: '2d' })
        .position((rand() * 2 - 1) * spanX, (rand() * 2 - 1) * spanY)
        .scale(size, size)
        .transparent();
      handles.push(h);
    }
  });
  await settledAt(n);
  await frames(8);
  out.scene = { N: n, zMode, quadPx: QUAD_PX, target: [WIDTH, HEIGHT], gpuEntityCount: await gpuCount(), lightingBackend: engine.lighting.backend };

  // rAF clock for the whole measurement.
  let rafs = 0;
  let counting = true;
  const rafTimes = [];
  const tick = (t) => { rafs++; rafTimes.push(t); if (counting) requestAnimationFrame(tick); };
  requestAnimationFrame(tick);

  // --- the first enable: builds the profiler (fresh query set) ---
  if (engine.renderer.graph.profiler !== null) throw new Error('a profiler is already attached: reload the page');
  const enabled = engine.enableGpuProfiling();
  if (!enabled) throw new Error('enableGpuProfiling() returned false');
  const profiler = engine.renderer.graph.profiler;
  const history = profiler.history;
  out.profilerAtFirstEnable = { generation: profiler.generation, seal: profiler.seal, discarded: profiler.discardedFrames, fresh: profiler.generation === 1 && profiler.seal === 0 };

  // --- the temporary wrapper ---
  const origConsume = Object.getPrototypeOf(profiler).consume;
  const origRecord = Object.getPrototypeOf(history).record;
  let logMode = 'log';
  let log = [];
  let lastConsumed = null;
  let current = null;
  const reasonDelta = (a, b) => Object.keys(b).filter((k) => b[k] !== a[k]);
  profiler.consume = function (entry) {
    const reasonsBefore = this.discardReasons;
    const pushedBefore = this.window.frames;
    current = { pairs: entry.pairs.map((p) => [p.name, p.work ? 1 : 0]), generation: entry.generation, profilerGeneration: this.generation, stamps: null };
    try {
      return origConsume.call(this, entry);
    } finally {
      const pushed = this.window.frames - pushedBefore;
      const reasons = reasonDelta(reasonsBefore, this.discardReasons);
      current.outcome = pushed === 1 ? 'ok' : reasons.length ? reasons.join('+') : 'dropped (older generation)';
      if (current.stamps) lastConsumed = current;
      if (logMode === 'log' && log.length < LOG_MAX) log.push(current);
      current = null;
    }
  };
  history.record = function (stamps) {
    if (current) current.stamps = Array.from(stamps);
    return origRecord.call(this, stamps);
  };

  const analyse = (records, before) => {
    let prev = before;
    return records.map((f, k) => {
      const row = { k, outcome: f.outcome, generationMatch: f.generation === f.profilerGeneration, pairs: f.pairs.length, worked: f.pairs.filter((p) => p[1]).length };
      if (!f.stamps) { row.stamps = 'none (not executed or not recorded)'; return row; }
      const worked = [];
      f.pairs.forEach(([name, work], i) => { if (work) worked.push({ i, name, b: f.stamps[2 * i], e: f.stamps[2 * i + 1] }); });
      if (worked.length === 0) { row.stamps = 'no worked pair'; prev = f; return row; }
      const cmp = (x, y) => (x < y ? -1 : x > y ? 1 : 0);
      const bs = worked.map((w) => w.b).sort(cmp);
      const es = worked.map((w) => w.e).sort(cmp);
      const medB = bs[bs.length >> 1];
      const medE = es[es.length >> 1];
      row.spanMs = Number(es[es.length - 1] - bs[0]) / 1e6;
      const offs = worked.map((w) => ({ name: w.name, i: w.i, b: Number(w.b - medB) / 1e6, e: Number(w.e - medE) / 1e6 }));
      row.maxAbsOffsetFromMedianMs = Math.max(...offs.map((o) => Math.max(Math.abs(o.b), Math.abs(o.e))));
      row.extremePair = offs.reduce((a, o) => (Math.max(Math.abs(o.b), Math.abs(o.e)) > Math.max(Math.abs(a.b), Math.abs(a.e)) ? o : a));
      row.zeroPairs = worked.filter((w) => w.b === 0n || w.e === 0n).map((w) => w.name);
      row.reversedPairs = worked.filter((w) => w.e < w.b).map((w) => w.name);
      row.repeatsPrevious = prev && prev.stamps
        ? worked.filter((w) => 2 * w.i + 1 < prev.stamps.length && (prev.stamps[2 * w.i] === w.b || prev.stamps[2 * w.i + 1] === w.e)).map((w) => `${w.i}:${w.name}`)
        : 'no previous frame';
      prev = f;
      return row;
    });
  };
  const rawFrame = (f) => (f ? { outcome: f.outcome, pairs: f.pairs, stamps: f.stamps ? f.stamps.map(String) : null } : null);
  const sortEntries = (timings) => timings.filter((t) => t.name.startsWith('transparent-sort/'));
  const fps = (from) => {
    const ts = rafTimes.slice(from);
    return ts.length > 1 ? ((ts.length - 1) * 1000) / (ts[ts.length - 1] - ts[0]) : null;
  };

  const measureFirst = async (label, before) => {
    const t0 = performance.now();
    const r0 = rafs;
    const reasons0 = profiler.discardReasons;
    await until(`${WINDOW} valid frames (${label})`, async () => profiler.window.frames >= WINDOW);
    const timings = engine.getGpuTimings();
    const frame = engine.getGpuFrameTiming();
    const reasons1 = profiler.discardReasons;
    logMode = 'track';
    const records = log;
    log = [];
    const rows = analyse(records, before);
    const withStamps = rows.filter((r) => r.spanMs !== undefined);
    return {
      label,
      elapsedMs: performance.now() - t0,
      rafFrames: rafs - r0,
      fps: fps(r0),
      validFrames: profiler.window.frames,
      consumedFramesLogged: records.length,
      discardsInWindow: Object.fromEntries(Object.keys(reasons1).map((k) => [k, reasons1[k] - reasons0[k]])),
      skippedFrames: profiler.skippedFrames,
      frame,
      timings,
      sortEntries: sortEntries(timings).map((t) => t.name),
      graphOrder: engine.renderer.graph.executionOrder,
      summary: {
        frames: rows.length,
        outcomes: rows.reduce((m, r) => ({ ...m, [r.outcome]: (m[r.outcome] ?? 0) + 1 }), {}),
        framesRepeatingPrevious: rows.filter((r) => Array.isArray(r.repeatsPrevious) && r.repeatsPrevious.length > 0).map((r) => ({ k: r.k, pairs: r.repeatsPrevious })),
        framesWithZeroPairs: rows.filter((r) => r.zeroPairs?.length).map((r) => r.k),
        framesWithReversedPairs: rows.filter((r) => r.reversedPairs?.length).map((r) => r.k),
        maxAbsOffsetFromMedianMs: Math.max(...withStamps.map((r) => r.maxAbsOffsetFromMedianMs)),
        spanMs: {
          first: withStamps[0]?.spanMs ?? null,
          min: Math.min(...withStamps.map((r) => r.spanMs)),
          median: withStamps.map((r) => r.spanMs).sort((a, b) => a - b)[withStamps.length >> 1],
          max: Math.max(...withStamps.map((r) => r.spanMs)),
        },
        firstFrameComparedWith: before ? 'the last frame consumed before the reset (frames in flight at the reset are never consumed)' : 'nothing: no frame before it',
      },
      rows,
      rawFirstFrames: records.slice(0, 2).map(rawFrame),
    };
  };

  try {
  // --- first window ---
  out.first = await measureFirst('first 120 valid frames after the first enableGpuProfiling() (fresh profiler, fresh query set)', null);

  // --- steady window, no reset ---
  {
    const t0 = performance.now();
    const r0 = rafs;
    const reasons0 = profiler.discardReasons;
    const skipped0 = profiler.skippedFrames;
    const valid0 = profiler.window.frames;
    await until(`${STEADY_FRAMES} rAF frames`, async () => rafs - r0 >= STEADY_FRAMES);
    const timings = engine.getGpuTimings();
    const frame = engine.getGpuFrameTiming();
    const reasons1 = profiler.discardReasons;
    out.steady = {
      label: `${STEADY_FRAMES} rAF frames right after the first window, no reset`,
      elapsedMs: performance.now() - t0,
      rafFrames: rafs - r0,
      fps: fps(r0),
      validFrames: profiler.window.frames - valid0,
      discardsInWindow: Object.fromEntries(Object.keys(reasons1).map((k) => [k, reasons1[k] - reasons0[k]])),
      discardReasonsTotal: reasons1,
      skippedFramesInWindow: profiler.skippedFrames - skipped0,
      frame,
      timings,
      sortEntries: sortEntries(timings).map((t) => t.name),
      spansOfLastWindow: [...profiler.window.spans],
      graphOrder: engine.renderer.graph.executionOrder,
      entityCount: engine.stats.entityCount,
      gpuEntityCount: await gpuCount(),
    };
  }

  // --- reset window: disable + enable in one turn ---
  const beforeReset = lastConsumed;
  logMode = 'log';
  log = [];
  engine.disableGpuProfiling();
  engine.enableGpuProfiling();
  out.profilerAfterReset = { sameInstance: engine.renderer.graph.profiler === profiler, generation: profiler.generation };
  out.reset = await measureFirst('first 120 valid frames after disableGpuProfiling(); enableGpuProfiling() (reset: same query set, history forgotten)', beforeReset);
  out.lastFrameBeforeReset = rawFrame(beforeReset);

  } finally {
    // --- teardown (also on an error) ---
    counting = false;
    out.discardReasonsTotal = profiler.discardReasons;
    engine.disableGpuProfiling();
    delete profiler.consume;
    delete history.record;
  }
  out.wrapperRemoved = !Object.prototype.hasOwnProperty.call(profiler, 'consume') && !Object.prototype.hasOwnProperty.call(history, 'record')
    && profiler.consume === origConsume && history.record === origRecord;
  for (const h of handles) h.destroy();
  await settledAt(0);
  await frames(4);
  out.endedAt = new Date().toISOString();
  out.timeOriginAtEnd = performance.timeOrigin;
  out.visibilityAtEnd = document.visibilityState;
  out.visChanges = window.__visChanges ?? null;
  out.viteWsCloses = window.__viteWsCloses ?? null;
  out.cap = window.__cap ?? null;
  out.canvas = [document.getElementById('canvas').width, document.getElementById('canvas').height];
  out.dpr = devicePixelRatio;
  out.mode = engine.mode;
  out.crossOriginIsolated = window.crossOriginIsolated === true;
  out.navigatorGpu = !!navigator.gpu;
  return out;
}
